// The content build for imorchy.dev: turns site/content/ into committed pages, the Atom feed and the sitemap.
// ADR "Static content build and phase-1 access for imorchy.dev", points 1-3. Node built-ins only, no packages.
//
//   node site/build.mjs           write the output files (run it before you commit a content change); like --check,
//                                 it exits 1 if a generated file's source is gone (it lists the file; you delete it)
//   node site/build.mjs --check   rebuild in memory; fail if a source breaks a rule or a committed output is stale
//
// Sources: content/pages.json (the hand-written pages and the date each last really changed),
// content/blog/<YYYY-MM-DD>-<slug>.md and content/changelog/<YYYY-MM-DD>-<slug>.md (front matter + markdown).
// Output: sitemap.xml always; blog.html, blog/<slug>.html, changelog.html and feed.xml once there's an entry for them.
// The output depends only on the sources (dates come from front matter or pages.json, never the clock or mtimes), so
// the same sources give the same bytes. Generated pages load /styles.css and nothing else: no script but JSON-LD.
// build.mjs and content/ are never uploaded (worker/files.mjs).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { skipDir } from "./worker/files.mjs";
import { ORIGIN } from "./worker/urls.mjs";

const SITE = path.dirname(fileURLToPath(import.meta.url));
const MARK = "<!-- generated by site/build.mjs from site/content: edit the source, then run node site/build.mjs -->";
const OG_DEFAULT = "/assets/og-image.png";
/** The index page each kind of entry gets. Changelog entries live on their index; blog posts get their own page. */
const KINDS = {
  blog: { index: "/blog", title: "Blog", description: "Notes from the team building Orchy AI, a command center for AI agents on your own computer.", pages: true },
  changelog: { index: "/changelog", title: "Changelog", description: "What changed in Orchy AI, release by release.", pages: false },
};
const FIELDS = { blog: ["title", "description", "date", "updated", "og_image", "canonical"], changelog: ["title", "description", "date", "updated", "security"] };
const REQUIRED = { blog: ["title", "description", "date", "og_image", "canonical"], changelog: ["title", "description", "date", "security"] };

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
// Line ends and a UTF-8 BOM (Windows editors add one) don't count.
const lf = (s) => s.replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n");
const realDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && new Date(d + "T00:00:00Z").toISOString().slice(0, 10) === d;
export const fileFor = (p) => (p === "/" ? "index.html" : path.extname(p) ? p.slice(1) : p.slice(1) + ".html");

/** Front matter (`key: value` lines between `---` fences) and the markdown after it. */
export function parseSource(text) {
  const m = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(lf(text));
  if (!m) return { meta: null, body: lf(text), bad: [] };
  const meta = {};
  const bad = [];
  for (const line of m[1].split("\n").filter((l) => l.trim())) {
    const kv = /^([a-z_]+):\s*(.*)$/.exec(line);
    if (!kv) bad.push(line);
    else meta[kv[1]] = kv[2].trim().replace(/^"(.*)"$/, "$1");
  }
  return { meta, body: m[2], bad };
}

// Links may go to https://, a site path or a fragment. Anything else (javascript:, data:) renders as plain text.
const safeHref = (href) => /^(https:\/\/|\/(?![\/\\])|#)/.test(href);
function inline(text) {
  // Code spans and link targets are set aside first, so emphasis never reaches inside them.
  const held = [];
  const hold = (html) => `\u0000${held.push(html) - 1}\u0000`;
  return esc(text)
    .replace(/`([^`]+)`/g, (_, c) => hold(`<code>${c}</code>`))
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, t, href) => (safeHref(href) ? `${hold(`<a href="${href}">`)}${t}${hold("</a>")}` : t))
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^\w*])\*(?!\s)([^*]+?)(?<!\s)\*(?![\w*])/g, "$1<em>$2</em>")
    .replace(/\u0000(\d+)\u0000/g, (_, i) => held[i]);
}
const BLOCK = /^(```|#{1,5}\s|>|[-*]\s|\d+\.\s|\|)/;
const TABLE_ROW = /^\|[^\n]*\|\s*$/;
const TABLE_RULE = /^\|(\s*:?-+:?\s*\|)+\s*$/;
const cells = (row) => row.trim().slice(1, -1).split("|").map((c) => c.trim());
/**
 * The markdown subset: headings, paragraphs, lists, blockquotes, pipe tables, fenced code, inline code, emphasis and
 * links. Every character of text is HTML-escaped. Headings shift down one level (# → h2): the page title is the only
 * h1. A table sits in a focusable, labelled scroll box so it stays readable on a 360px phone.
 */
export function markdown(md) {
  const lines = lf(md).split("\n");
  const out = [];
  for (let i = 0; i < lines.length; ) {
    const line = lines[i];
    let m;
    if (!line.trim()) i++;
    else if (line.startsWith("```")) {
      const code = [];
      while (++i < lines.length && !lines[i].startsWith("```")) code.push(lines[i]);
      i++;
      out.push(`<pre><code>${esc(code.join("\n"))}</code></pre>`);
    } else if ((m = /^(#{1,5})\s+(.*)$/.exec(line))) {
      out.push(`<h${m[1].length + 1}>${inline(m[2])}</h${m[1].length + 1}>`);
      i++;
    } else if (line.startsWith(">")) {
      const quote = [];
      while (i < lines.length && lines[i].startsWith(">")) quote.push(lines[i++].replace(/^>\s?/, ""));
      out.push(`<blockquote>${markdown(quote.join("\n"))}</blockquote>`);
    } else if (TABLE_ROW.test(line) && TABLE_RULE.test(lines[i + 1] || "")) {
      const head = cells(line);
      const rows = [];
      for (i += 2; i < lines.length && TABLE_ROW.test(lines[i]); i++) rows.push(cells(lines[i]));
      const label = esc(`Table: ${head.join(", ").replace(/[*`]/g, "")}`);
      const th = head.map((c) => `<th scope="col">${inline(c)}</th>`).join("");
      const body = rows.map((r) => `<tr>${r.map((c) => `<td>${inline(c)}</td>`).join("")}</tr>`).join("");
      out.push(`<div class="table-scroll" role="region" tabindex="0" aria-label="${label}"><table><thead><tr>${th}</tr></thead><tbody>${body}</tbody></table></div>`);
    } else if (/^([-*]|\d+\.)\s/.test(line)) {
      const tag = /^\d/.test(line) ? "ol" : "ul";
      // [^\n] rather than ., so a pasted U+2028 can't make the opening line fail to match (and loop forever).
      const item = tag === "ol" ? /^\d+\.\s+([^\n]*)$/ : /^[-*]\s+([^\n]*)$/;
      const items = [];
      while (i < lines.length && (m = item.exec(lines[i]))) (items.push(`<li>${inline(m[1])}</li>`), i++);
      if (!items.length) i++;
      out.push(`<${tag}>${items.join("")}</${tag}>`);
    } else {
      const para = [line.trim()];
      while (++i < lines.length && lines[i].trim() && !BLOCK.test(lines[i])) para.push(lines[i].trim());
      out.push(`<p>${inline(para.join(" "))}</p>`);
    }
  }
  return out.join("\n");
}

/** What's wrong with a page for search engines: self-canonical, indexable, one h1, title, description, og:image, JSON-LD that parses. */
export function seoProblems(html, pagePath) {
  const problems = [];
  const canon = canonicals(html);
  if (canon.length !== 1 || canon[0] !== ORIGIN + pagePath) problems.push(`canonical: got ${JSON.stringify(canon)}, want ["${ORIGIN + pagePath}"]`);
  if (/<meta\b[^>]*\bname="robots"[^>]*\bcontent="[^"]*noindex/i.test(html)) problems.push("has a noindex robots meta");
  const h1 = (html.match(/<h1\b/g) || []).length;
  if (h1 !== 1) problems.push(`${h1} <h1> (want 1)`);
  if ((html.match(/<title>[^<]*\S[^<]*<\/title>/g) || []).length !== 1) problems.push("needs one non-empty <title>");
  if (!/<meta\b[^>]*\bname="description"[^>]*\bcontent="[^"]*[^"\s]/.test(html)) problems.push("no meta description");
  if (!/<meta\b[^>]*\bproperty="og:image"[^>]*\bcontent="https:\/\/imorchy\.dev\/[^"]+"/.test(html)) problems.push("no og:image on imorchy.dev");
  const blocks = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  if (!blocks.length) problems.push("no JSON-LD block");
  blocks.forEach((b, i) => {
    try {
      JSON.parse(b);
    } catch (e) {
      problems.push(`JSON-LD block ${i + 1} doesn't parse: ${e.message}`);
    }
  });
  return problems;
}
/** Every canonical href in a page (a page should have exactly one). */
export const canonicals = (html) => [...html.matchAll(/<link\b[^>]*\brel="canonical"[^>]*>/g)].map((m) => /\bhref="([^"]*)"/.exec(m[0])?.[1]);

/** ADR point 3: a generated page loads no WebGL, no hero bundle and no script file. */
export function generatedProblems(html) {
  const problems = [];
  if (/<script\b(?![^>]*type="application\/ld\+json")/.test(html)) problems.push("a <script> that isn't JSON-LD");
  if (/<canvas\b/.test(html)) problems.push("a <canvas>");
  for (const s of ["importmap", "three.module", "cdn.jsdelivr.net", "js/main.mjs"]) if (html.includes(s)) problems.push(`loads ${s}`);
  return problems;
}

/**
 * The site footer, one source for every page (Jan, 2026-11-03): page() puts it on the generated pages and build()
 * stamps it over the one <footer> of each hand-written page in pages.json, so --check fails if any page drifts.
 * Columns are data: a new group is one more row.
 */
export const FOOTER_COLUMNS = [
  { heading: "Product", links: [["Approvals", "/approvals"], ["Client workspaces", "/client-workspaces"], ["Claude Code orchestrator", "/claude-code-orchestrator"], ["Local command center", "/local"]] },
  { heading: "Resources", links: [["Changelog", "/changelog"], ["RSS feed", "/feed.xml"]] },
  { heading: "Legal", links: [["Privacy", "/privacy"], ["Terms", "/terms"], ["Security", "/security"], ["Data Privacy", "/data-privacy"]] },
  { heading: "Follow", links: [["Facebook", "https://www.facebook.com/OrchyAI/"], ["YouTube", "https://www.youtube.com/@orchy-ai"]] },
];
const FOOTER_TAG = /[ \t]*<footer\b[\s\S]*?<\/footer>/g;
export function footer(p) {
  const top = p === "/" ? "#top" : "/";
  const attrs = (href) => (/^https:/.test(href) ? ' target="_blank" rel="noopener noreferrer"' : href === p ? ' aria-current="page"' : "");
  const cols = FOOTER_COLUMNS.map(
    ({ heading, links }) =>
      `          <div class="footer-col">\n            <h2 class="footer-heading">${esc(heading)}</h2>\n            <ul>\n${links.map(([text, href]) => `              <li><a href="${href}"${attrs(href)}>${esc(text)}</a></li>\n`).join("")}            </ul>\n          </div>\n`,
  );
  return `    <footer class="footer wrap">
      <div class="footer-top" data-perch>
        <div class="footer-brand">
          <a class="brand" href="${top}" aria-label="${p === "/" ? "Back to top" : "Orchy AI home"}"><img class="brand-logo" src="/assets/orchy-main-128.webp" width="42" height="42" alt="" /><span>Orchy</span></a>
          <p class="footer-tagline">A command center for your AI agents, on your own computer.</p>
          <a class="footer-back" href="${top}">${p === "/" ? "Back to the Top" : "Back to Home"}</a>
        </div>
        <nav class="footer-nav" aria-label="Footer">
${cols.join("")}        </nav>
      </div>
      <p class="footer-wordmark" aria-hidden="true">Orchy</p>
    </footer>`;
}

const ld = (data) => JSON.stringify(data, null, 2).replace(/</g, "\\u003c").replace(/^/gm, "      ");
function page({ path: p, title, description, image = OG_DEFAULT, data, body }) {
  return `<!doctype html>
${MARK}
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${esc(title)} | Orchy AI</title>
    <meta name="description" content="${esc(description)}" />
    <meta name="theme-color" content="#080a0d" />
    <link rel="canonical" href="${ORIGIN}${p}" />
    <meta property="og:type" content="article" />
    <meta property="og:site_name" content="Orchy AI" />
    <meta property="og:url" content="${ORIGIN}${p}" />
    <meta property="og:title" content="${esc(title)} | Orchy AI" />
    <meta property="og:description" content="${esc(description)}" />
    <meta property="og:image" content="${ORIGIN}${image}" />
    <meta name="twitter:card" content="summary_large_image" />
    <script type="application/ld+json">
${ld({ "@context": "https://schema.org", ...data, url: ORIGIN + p })}
    </script>
    <link rel="icon" href="/assets/orchy-icon-64.png" type="image/png" sizes="64x64" />
    <link rel="preload" href="/fonts/JetBrainsMono-Regular.woff2" as="font" type="font/woff2" crossorigin />
    <link rel="stylesheet" href="/styles.css" />
  </head>
  <body>
    <a class="skip" href="#main">Skip to content</a>
    <header class="nav">
      <div class="nav-inner wrap">
        <a class="brand" href="/" aria-label="Orchy AI home"><img class="brand-logo" src="/assets/orchy-main-128.webp" width="34" height="34" alt="" /><span>Orchy</span></a>
      </div>
    </header>
    <main id="main" class="answer wrap">
      <article>
        <h1>${esc(title)}</h1>
${body}
      </article>
    </main>
${footer(p)}
  </body>
</html>
`;
}
const when = (e) => `<p class="answer-lede"><time datetime="${e.date}">${e.date}</time>${e.updated ? `, updated <time datetime="${e.updated}">${e.updated}</time>` : ""}</p>`;

/** Every content entry of a kind, newest first, with its problems. */
function entries(site, kind, today, problems) {
  const dir = path.join(site, "content", kind);
  if (!fs.existsSync(dir)) return [];
  const list = [];
  for (const name of fs.readdirSync(dir).sort()) {
    const where = `content/${kind}/${name}`;
    const named = /^(\d{4}-\d{2}-\d{2})-([a-z0-9]+(?:-[a-z0-9]+)*)\.md$/.exec(name);
    if (!named) {
      problems.push(`${where}: name it <YYYY-MM-DD>-<slug>.md (lowercase slug)`);
      continue;
    }
    const { meta, body, bad } = parseSource(fs.readFileSync(path.join(dir, name), "utf8"));
    if (!meta) {
      problems.push(`${where}: no front matter`);
      continue;
    }
    const e = { kind, slug: named[2], ...meta, body, where };
    bad.forEach((l) => problems.push(`${where}: bad front matter line ${JSON.stringify(l)}`));
    for (const k of Object.keys(meta)) if (!FIELDS[kind].includes(k)) problems.push(`${where}: unknown field "${k}"`);
    for (const k of REQUIRED[kind]) if (!meta[k]) problems.push(`${where}: missing ${k}`);
    for (const k of ["date", "updated"]) {
      if (meta[k] === undefined) continue;
      if (!realDate(meta[k])) problems.push(`${where}: ${k} ${JSON.stringify(meta[k])} isn't a real YYYY-MM-DD`);
      else if (meta[k] > today) problems.push(`${where}: ${k} ${meta[k]} is after today (${today}); no scheduled posts`);
    }
    if (meta.date && meta.date !== named[1]) problems.push(`${where}: date ${meta.date} doesn't match the file name`);
    if (meta.updated && meta.updated < meta.date) problems.push(`${where}: updated is before date`);
    if (kind === "blog") {
      e.path = `/blog/${e.slug}`;
      if (meta.canonical && meta.canonical !== ORIGIN + e.path) problems.push(`${where}: canonical must be ${ORIGIN + e.path}`);
      if (meta.og_image && !(/^\/assets\/[\w./-]+$/.test(meta.og_image) && !meta.og_image.includes("..") && fs.existsSync(path.join(site, meta.og_image))))
        problems.push(`${where}: og_image ${meta.og_image} isn't a file under site/assets/`);
    } else {
      if (!["true", "false"].includes(meta.security)) problems.push(`${where}: security must be true or false`);
      e.security = meta.security === "true";
      // ADR point 10: a security entry says what was affected and what to do, never how to exploit it.
      if (e.security && /`/.test(body)) problems.push(`${where}: a security entry can't have code`);
      // Jan, 2026-11-03: the changelog says what changed for readers, never which pull request did it.
      if (/\bPR\s*#\d+|\/pull\//i.test(body)) problems.push(`${where}: no PR numbers or /pull/ links in the changelog`);
    }
    e.lastmod = meta.updated || meta.date;
    list.push(e);
  }
  return list.sort((a, b) => (b.date + b.slug < a.date + a.slug ? -1 : 1));
}

/**
 * Build the site from its sources, in memory. Returns the output files (site-relative path → text), the problems
 * that fail the build, and a regression-list row (urls.mjs shape) for every generated page.
 */
// "today" (only for the not-after-today check) is the UTC date, like CI's clock; a post dated tomorrow in UTC waits a day.
export function build(site = SITE, { today = new Date().toISOString().slice(0, 10) } = {}) {
  const problems = [];
  const files = new Map();
  const pages = [];
  const sitemap = [];
  let hand = [];
  try {
    const list = JSON.parse(lf(fs.readFileSync(path.join(site, "content", "pages.json"), "utf8")));
    if (!Array.isArray(list)) throw new Error("must be a list of { path, lastmod }");
    hand = list;
  } catch (e) {
    problems.push(`content/pages.json: ${e.message}`);
  }
  for (const { path: p, lastmod } of hand) {
    const file = path.join(site, fileFor(String(p)));
    if (!/^\/[a-z0-9/-]*$/.test(p) || !fs.existsSync(file)) problems.push(`content/pages.json: ${p} has no page file`);
    else {
      const html = lf(fs.readFileSync(file, "utf8"));
      seoProblems(html, p).forEach((m) => problems.push(`${fileFor(p)}: ${m}`));
      if ((html.match(FOOTER_TAG) || []).length !== 1) problems.push(`${fileFor(p)}: needs exactly one <footer> (build.mjs writes the shared footer there)`);
      else files.set(fileFor(p), html.replace(FOOTER_TAG, () => footer(p)));
    }
    if (!realDate(lastmod) || lastmod > today) problems.push(`content/pages.json: ${p} lastmod ${lastmod} isn't a real date up to today`);
    sitemap.push({ path: p, lastmod });
  }
  const all = [];
  for (const [kind, k] of Object.entries(KINDS)) {
    const list = entries(site, kind, today, problems);
    if (!list.length) continue;
    all.push(...list);
    const newest = list.map((e) => e.lastmod).sort().at(-1);
    const items = list.map((e) =>
      k.pages
        ? `        <section><h2><a href="${e.path}">${esc(e.title)}</a></h2>\n        ${when(e)}\n        <p>${esc(e.description)}</p></section>`
        : `        <section id="${e.slug}"><h2>${esc(e.title)}</h2>\n        ${when(e)}\n${e.security ? "        <p><strong>Security fix.</strong> Update to the latest version.</p>\n" : ""}${markdown(e.body)}</section>`,
    );
    const data = kind === "blog" ? { "@type": "Blog", name: "Orchy AI blog", blogPost: list.map((e) => ({ "@type": "BlogPosting", headline: e.title, url: ORIGIN + e.path, datePublished: e.date })) } : { "@type": "WebPage", name: "Orchy AI changelog", dateModified: newest };
    files.set(fileFor(k.index), page({ path: k.index, title: k.title, description: k.description, data, body: items.join("\n") }));
    pages.push({ path: k.index, title: k.title });
    sitemap.push({ path: k.index, lastmod: newest });
    for (const e of k.pages ? list : []) {
      const data = { "@type": "BlogPosting", headline: e.title, description: e.description, datePublished: e.date, dateModified: e.lastmod, image: ORIGIN + e.og_image, author: { "@type": "Organization", name: "Orchy AI" }, publisher: { "@type": "Organization", name: "Orchy AI" } };
      files.set(fileFor(e.path), page({ path: e.path, title: e.title, description: e.description, image: e.og_image, data, body: `        ${when(e)}\n${markdown(e.body)}\n        <p><a href="${k.index}">All posts</a></p>` }));
      pages.push({ path: e.path, title: e.title });
      sitemap.push({ path: e.path, lastmod: e.lastmod });
    }
  }
  // Canonical must be ORIGIN + path (entries()), so a duplicate slug is the only way two entries can collide.
  all.map((e) => e.kind + "/" + e.slug).filter((v, i, a) => a.indexOf(v) !== i).forEach((v) => problems.push(`duplicate slug: ${v}`));
  for (const { path: p } of pages) {
    if (hand.some((h) => h.path === p)) problems.push(`content/pages.json: ${p} is a generated page; a hand-written file there would be overwritten`);
    const html = files.get(fileFor(p));
    [...seoProblems(html, p), ...generatedProblems(html)].forEach((m) => problems.push(`${fileFor(p)} (generated): ${m}`));
  }
  if (all.length) files.set("feed.xml", feed(all));
  const urls = sitemap.map((r) => `  <url>\n    <loc>${ORIGIN}${r.path}</loc>\n    <lastmod>${r.lastmod}</lastmod>\n  </url>\n`).join("");
  files.set("sitemap.xml", `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}</urlset>\n`);
  const rows = pages.map(({ path: p, title }) => ({ path: p, type: "text/html", profile: "page", markers: [`<h1>${esc(title)}</h1>`], generated: true }));
  return { files, problems, pages: rows };
}

function feed(all) {
  const list = [...all].sort((a, b) => (b.lastmod + b.slug < a.lastmod + a.slug ? -1 : 1));
  const id = (e) => (e.kind === "blog" ? ORIGIN + e.path : `${ORIGIN}/changelog#${e.slug}`);
  const entry = (e) =>
    `  <entry>\n    <id>${id(e)}</id>\n    <title>${esc(e.title)}</title>\n    <link href="${id(e)}"/>\n    <published>${e.date}T00:00:00Z</published>\n    <updated>${e.lastmod}T00:00:00Z</updated>\n    <summary>${esc(e.description)}</summary>\n  </entry>\n`;
  return `<?xml version="1.0" encoding="UTF-8"?>\n${MARK}\n<feed xmlns="http://www.w3.org/2005/Atom">\n  <id>${ORIGIN}/</id>\n  <title>Orchy AI</title>\n  <link href="${ORIGIN}/feed.xml" rel="self"/>\n  <link href="${ORIGIN}/"/>\n  <updated>${list[0].lastmod}T00:00:00Z</updated>\n  <author><name>Orchy AI</name></author>\n${list.map(entry).join("")}</feed>\n`;
}

/** Committed outputs that differ from a fresh build, and generated files whose source is gone. */
export function staleFiles(site, files) {
  const stale = [...files].filter(([rel, text]) => !fs.existsSync(path.join(site, rel)) || lf(fs.readFileSync(path.join(site, rel), "utf8")) !== text).map(([rel]) => rel);
  const walk = (dir) =>
    fs.readdirSync(dir, { withFileTypes: true }).flatMap((d) => {
      const full = path.join(dir, d.name);
      const rel = path.relative(site, full).split(path.sep).join("/");
      if (d.isDirectory()) return skipDir(rel, d.name) ? [] : walk(full);
      return /\.(html|xml)$/.test(d.name) && fs.readFileSync(full, "utf8").includes(MARK) ? [rel] : [];
    });
  return [...stale, ...walk(site).filter((rel) => !files.has(rel)).map((rel) => `${rel} (its source is gone: delete it)`)];
}

/** The command line, as a function so the tests run it in-process. Returns the exit code. */
export function cli(site, args, { log = console.log, error = console.error } = {}) {
  const { files, problems } = build(site);
  for (const p of problems) error(`build: ${p}`);
  if (problems.length) return 1;
  const check = args.includes("--check");
  if (!check) {
    for (const [rel, text] of files) {
      fs.mkdirSync(path.dirname(path.join(site, rel)), { recursive: true });
      fs.writeFileSync(path.join(site, rel), text);
    }
    log(`build: wrote ${[...files.keys()].join(", ")}`);
  }
  const stale = staleFiles(site, files);
  for (const rel of stale) error(check ? `build --check: site/${rel} is out of date: run node site/build.mjs and commit the result` : `build: site/${rel}`);
  if (stale.length) return 1;
  if (check) log(`build --check: ${files.size} generated file(s) match their sources`);
  return 0;
}

if (process.argv[1] && path.resolve(process.argv[1]).toLowerCase() === fileURLToPath(import.meta.url).toLowerCase())
  process.exitCode = cli(SITE, process.argv.slice(2));
